mapper.select:
select lock_id, baby_id, module_code, record_id, locker_user_id, locker_name, expire_time, heartbeat_time
  from nc_record_lock
 where module_code = #{moduleCode} and record_id = #{recordId}

mapper.update:
update nc_record_lock
   set expire_time = #{expireTime},
       heartbeat_time = current_timestamp,
       locker_user_id = #{lockerUserId},
       locker_name = #{lockerName}
 where module_code = #{moduleCode} and record_id = #{recordId}

mapper.delete:
delete from nc_record_lock
 where module_code = #{moduleCode} and record_id = #{recordId}
   and locker_user_id = #{userId}
